import{_ as e,o as a,c as r,a3 as s}from"./chunks/framework.BrO6lPIi.js";const g=JSON.parse('{"title":"子任务节点动画系统","description":"本文件聚焦“子任务节点动画系统”，即 Chrome 扩展侧边栏中，子任务执行时如何展示“当前正在执行的节点”、如何区分成功/失败/部分完成状态，以及如何在取消或完成后让动效正确停止。","frontmatter":{"title":"子任务节点动画系统","description":"本文件聚焦“子任务节点动画系统”，即 Chrome 扩展侧边栏中，子任务执行时如何展示“当前正在执行的节点”、如何区分成功/失败/部分完成状态，以及如何在取消或完成后让动效正确停止。"},"headers":[],"relativePath":"Chrome-扩展核心/Side-Panel-界面架构/子任务节点动画系统/index.md","filePath":"Chrome-扩展核心/Side-Panel-界面架构/子任务节点动画系统/index.md","lastUpdated":null}'),i={name:"Chrome-扩展核心/Side-Panel-界面架构/子任务节点动画系统/index.md"};function n(l,t,o,c,u,h){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="子任务节点动画系统" tabindex="-1">子任务节点动画系统 <a class="header-anchor" href="#子任务节点动画系统" aria-label="Permalink to &quot;子任务节点动画系统&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css" target="_blank" rel="noreferrer">src/side_panel/styles.css</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js" target="_blank" rel="noreferrer">src/background/react-loop.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-current-node-anim.unit.test.js" target="_blank" rel="noreferrer">test/unit/subtask-current-node-anim.unit.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-partial-outcome.unit.test.js" target="_blank" rel="noreferrer">test/unit/subtask-partial-outcome.unit.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-timeout-budget.unit.test.js" target="_blank" rel="noreferrer">test/unit/subtask-timeout-budget.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构定位">项目结构定位</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与可访问性">性能与可访问性</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件聚焦“子任务节点动画系统”，即 Chrome 扩展侧边栏中，子任务执行时如何展示“当前正在执行的节点”、如何区分成功/失败/部分完成状态，以及如何在取消或完成后让动效正确停止。该系统横跨三个层面：</p><ul><li><strong>后台执行层</strong>：负责子任务计划、节点执行、进度回写与超时控制。</li><li><strong>界面渲染层</strong>：负责把子任务清单、节点列表、当前执行节点、统计按钮等渲染到 DOM。</li><li><strong>样式与动效层</strong>：通过 CSS 变量 Token 体系实现呼吸底、左侧光条、旋转环、图标脉冲等动效，并保证在取消/完成后自动静止。</li></ul><p>该系统的目标是让用户在几十上百个节点中，一眼看出“到底哪一条在跑”，同时避免“取消后还在转圈”“已完成节点误以为仍在运行”等常见交互问题。</p><h2 id="项目结构定位" tabindex="-1">项目结构定位 <a class="header-anchor" href="#项目结构定位" aria-label="Permalink to &quot;项目结构定位&quot;">​</a></h2><p>子任务节点动画系统主要位于以下路径：</p><table tabindex="0"><thead><tr><th>层级</th><th>文件</th><th>职责</th></tr></thead><tbody><tr><td>后台执行</td><td><code>src/background/react-loop.js</code></td><td>生成子任务计划、执行子任务、记录部分完成进度、计算超时预算</td></tr><tr><td>界面逻辑</td><td><code>src/side_panel/chat-manager.js</code></td><td>解析子任务清单、渲染待执行行/活动行/节点列表、处理过滤点击、分类最终结果</td></tr><tr><td>流式清理</td><td><code>src/side_panel/chat-streaming.js</code></td><td>取消流时的 UI 收尾，包括摘掉活动态、还原静态状态位</td></tr><tr><td>样式与动效</td><td><code>src/side_panel/styles.css</code></td><td>定义子任务卡片、节点行、当前节点强调、部分完成、reduced-motion 降级</td></tr><tr><td>回归测试</td><td><code>test/unit/subtask-current-node-anim.unit.test.js</code></td><td>验证当前节点动效作用域、取消链路、主题 Token 使用</td></tr><tr><td>语义修复测试</td><td><code>test/unit/subtask-partial-outcome.unit.test.js</code></td><td>验证“部分完成”三态与失败上报摘要</td></tr><tr><td>超时预算测试</td><td><code>test/unit/subtask-timeout-budget.unit.test.js</code></td><td>验证子任务超时放开、中断原因口径、已完成节点摘要回灌</td></tr></tbody></table><pre class="mermaid">graph TB
RL[&quot;后台执行&lt;br/&gt;react-loop.js&quot;] --&gt; CM[&quot;界面渲染&lt;br/&gt;chat-manager.js&quot;]
CM --&gt; CS[&quot;流式清理&lt;br/&gt;chat-streaming.js&quot;]
CM --&gt; STY[&quot;样式与动效&lt;br/&gt;styles.css&quot;]
TEST1[&quot;动效回归测试&lt;br/&gt;subtask-current-node-anim.unit.test.js&quot;] --&gt; CM
TEST1 --&gt; STY
TEST2[&quot;部分完成语义测试&lt;br/&gt;subtask-partial-outcome.unit.test.js&quot;] --&gt; CM
TEST3[&quot;超时预算测试&lt;br/&gt;subtask-timeout-budget.unit.test.js&quot;] --&gt; RL
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2902-L2989" target="_blank" rel="noreferrer">src/background/react-loop.js#L2902-L2989</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L902</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4053-L4430" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4053-L4430</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-current-node-anim.unit.test.js#L1-L115" target="_blank" rel="noreferrer">test/unit/subtask-current-node-anim.unit.test.js#L1-L115</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-partial-outcome.unit.test.js#L1-L21" target="_blank" rel="noreferrer">test/unit/subtask-partial-outcome.unit.test.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-timeout-budget.unit.test.js#L1-L24" target="_blank" rel="noreferrer">test/unit/subtask-timeout-budget.unit.test.js#L1-L24</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L902</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4053-L4430" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4053-L4430</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>子任务节点动画系统由四个关键能力组成：</p><ol><li><p><strong>子任务计划解析与权威清单</strong><br> 从后台下发的执行日志中提取 <code>nodeType=&#39;subtask_plan&#39;</code> 的权威子任务清单，用于界面展示“计划了哪些、还没执行到哪些”。</p></li><li><p><strong>节点过滤与统计</strong><br> 提供“✓N / ✗N / ⊘N”三类统计按钮，支持切换过滤状态；同一状态再点一次取消过滤，点击另一状态切换过滤。</p></li><li><p><strong>当前执行节点动效</strong><br> 当子任务处于活动态时，当前执行节点的状态位从静态“○”变为旋转环，整行出现呼吸底和左侧光条，节点图标有脉冲效果，文字加粗提亮。</p></li><li><p><strong>取消与完成后的动效收敛</strong><br> 取消流时移除 <code>.subtask-progress-active</code>，并把旋转环替换为静态“○”；完成或失败时也移除活动态，避免已完成节点继续动效。</p></li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L902</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4111-L4171" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4111-L4171</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>子任务节点动画系统的数据与控制流如下：</p><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant Panel as &quot;侧边栏界面&lt;br/&gt;chat-manager.js&quot;
participant Stream as &quot;流式处理&lt;br/&gt;chat-streaming.js&quot;
participant Background as &quot;后台执行&lt;br/&gt;react-loop.js&quot;
participant Styles as &quot;样式系统&lt;br/&gt;styles.css&quot;
User-&gt;&gt;Panel : 查看子任务卡片
Panel-&gt;&gt;Background : 读取执行日志/子任务计划
Background--&gt;&gt;Panel : subtask_plan + 节点状态更新
Panel-&gt;&gt;Panel : 渲染待执行行/活动行/节点列表
Panel-&gt;&gt;Styles : 添加 .subtask-progress-active
Styles--&gt;&gt;Panel : 显示旋转环/呼吸底/左侧光条
User-&gt;&gt;Stream : 点击停止/取消
Stream-&gt;&gt;Panel : finalizeCancelledStream
Stream-&gt;&gt;Styles : 移除 .subtask-progress-active
Stream-&gt;&gt;Panel : 状态位还原为静态 ○
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L829-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L829-L902</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2958-L2989" target="_blank" rel="noreferrer">src/background/react-loop.js#L2958-L2989</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4111-L4171" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4111-L4171</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="_1-子任务计划与节点渲染" tabindex="-1">1. 子任务计划与节点渲染 <a class="header-anchor" href="#_1-子任务计划与节点渲染" aria-label="Permalink to &quot;1. 子任务计划与节点渲染&quot;">​</a></h3><p>后台在执行主任务时，会生成权威子任务清单，并通过执行日志下发给侧边栏。界面侧通过解析 <code>subtask_plan</code> 消息，构建子任务条目数组，并按 index 升序插入容器，保证视觉顺序等于计划顺序。</p><p>关键点：</p><ul><li>权威清单来自后台，不是前端临时拼凑。</li><li>待执行行和活动行可能以不同顺序到达，因此必须按 <code>data-subtask-index</code> 排序插入。</li><li>未命中 plan 的消息或旧历史会自动降级为无清单模式。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;收到执行日志&quot;]) --&gt; Extract[&quot;提取 subtask_plan 清单&quot;]
Extract --&gt; HasPlan{&quot;是否命中权威清单？&quot;}
HasPlan --&gt; |是| BuildItems[&quot;构建子任务条目数组&quot;]
HasPlan --&gt; |否| Fallback[&quot;降级为无清单模式&quot;]
BuildItems --&gt; InsertOrder[&quot;按 index 升序插入容器&quot;]
InsertOrder --&gt; RenderPending[&quot;渲染待执行行&quot;]
RenderPending --&gt; RenderActive[&quot;渲染活动行/节点列表&quot;]
Fallback --&gt; End([&quot;结束&quot;])
RenderActive --&gt; End
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L829-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L829-L902</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L829-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L829-L902</a></li></ul><h3 id="_2-节点过滤与统计" tabindex="-1">2. 节点过滤与统计 <a class="header-anchor" href="#_2-节点过滤与统计" aria-label="Permalink to &quot;2. 节点过滤与统计&quot;">​</a></h3><p>节点过滤由两个纯函数驱动：</p><table tabindex="0"><thead><tr><th>函数</th><th>输入</th><th>输出</th><th>行为</th></tr></thead><tbody><tr><td><code>toggleNodeFilter</code></td><td>当前过滤状态、点击的目标状态</td><td>新过滤状态</td><td>同一状态再点取消，点击另一状态切换</td></tr><tr><td><code>applyNodeFilter</code></td><td>节点数组、过滤状态</td><td>过滤后的节点数组</td><td>success/failed 精确匹配，other 保留既非成功也非失败的节点</td></tr></tbody></table><p>UI 上，统计按钮带有 <code>data-node-filter</code>，点击后：</p><ul><li>切换 <code>_nodeFilter</code></li><li>若激活过滤，自动展开子任务卡片</li><li>调用 <code>_renderNodes</code> 重新渲染节点列表</li></ul><pre class="mermaid">flowchart TD
Click[&quot;点击 ✓N/✗N/⊘N&quot;] --&gt; Toggle[&quot;toggleNodeFilter(current, clicked)&quot;]
Toggle --&gt; FilterState{&quot;是否激活过滤？&quot;}
FilterState --&gt; |是| Expand[&quot;添加 subtask-expanded&quot;]
FilterState --&gt; |否| Collapse[&quot;保持或收起&quot;]
Expand --&gt; Render[&quot;_renderNodes()&quot;]
Collapse --&gt; Render
Render --&gt; Apply[&quot;applyNodeFilter(nodes, filter)&quot;]
Apply --&gt; UpdateDOM[&quot;更新节点显隐&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L822" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L822</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L867-L887" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L867-L887</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L822" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L822</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L867-L887" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L867-L887</a></li></ul><h3 id="_3-当前执行节点动效" tabindex="-1">3. 当前执行节点动效 <a class="header-anchor" href="#_3-当前执行节点动效" aria-label="Permalink to &quot;3. 当前执行节点动效&quot;">​</a></h3><p>当前执行节点动效的核心约束是：<strong>动效只应在子任务卡片处于活动态时生效</strong>。如果基础规则自带 animation，会导致已完成子任务中的未完成节点一直转圈；如果取消链路不摘掉活动态，用户点了停止后界面仍会假装在跑。</p><p>动效包含四层：</p><table tabindex="0"><thead><tr><th>动效</th><th>触发条件</th><th>表现</th></tr></thead><tbody><tr><td>状态位旋转环</td><td>子任务活动态 + 节点 processing</td><td>用 <code>&lt;span class=&quot;subtask-node-spinner&quot;&gt;</code> 替代静态 “○”</td></tr><tr><td>整行呼吸底</td><td>子任务活动态 + 节点 processing</td><td>背景色与左侧光条渐变</td></tr><tr><td>节点图标脉冲</td><td>子任务活动态 + 节点 processing</td><td>图标透明度与缩放变化</td></tr><tr><td>文字加粗提亮</td><td>子任务活动态 + 节点 processing</td><td>当前节点名称更醒目</td></tr></tbody></table><p>CSS 中所有颜色均使用主题 Token（如 <code>var(--brand-violet-rgb)</code>），不使用硬编码十六进制色值，从而兼容亮色、暗色和跟随系统主题。</p><pre class="mermaid">classDiagram
class SubtaskCard {
+string status
+boolean isRunning
+Array nodes
}
class NodeItem {
+string status
+string name
+boolean isProcessing
}
class Spinner {
+boolean isActive
+animationDuration
}
class BreatheEffect {
+backgroundGradient
+leftGlow
}
class IconPulse {
+opacityAnimation
+scaleAnimation
}
SubtaskCard --&gt; NodeItem : &quot;包含多个节点&quot;
SubtaskCard --&gt; Spinner : &quot;活动态时启用&quot;
SubtaskCard --&gt; BreatheEffect : &quot;processing 节点高亮&quot;
SubtaskCard --&gt; IconPulse : &quot;processing 节点图标脉冲&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4111-L4171" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4111-L4171</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L3697-L3697" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L3697-L3697</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4111-L4171" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4111-L4171</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-current-node-anim.unit.test.js#L31-L97" target="_blank" rel="noreferrer">test/unit/subtask-current-node-anim.unit.test.js#L31-L97</a></li></ul><h3 id="_4-取消链路与动效收敛" tabindex="-1">4. 取消链路与动效收敛 <a class="header-anchor" href="#_4-取消链路与动效收敛" aria-label="Permalink to &quot;4. 取消链路与动效收敛&quot;">​</a></h3><p>取消流程由 <code>finalizeCancelledStream</code> 负责。它需要完成三件事：</p><ol><li>移除所有 <code>.subtask-progress-active</code>，使呼吸底和旋转环停止。</li><li>把所有 <code>.subtask-node-spinner</code> 替换为静态 “○”，避免“取消后还在转圈”。</li><li>移除其他 streaming 相关动画元素，并标记消息为已取消。</li></ol><pre class="mermaid">flowchart TD
Cancel[&quot;用户点击停止&quot;] --&gt; Finalize[&quot;finalizeCancelledStream(element)&quot;]
Finalize --&gt; RemoveActive[&quot;移除 .subtask-progress-active&quot;]
RemoveActive --&gt; ReplaceSpinner[&quot;替换 .subtask-node-spinner 为 ○&quot;]
ReplaceSpinner --&gt; CleanupOther[&quot;移除其他 spinner 与 streaming 类&quot;]
CleanupOther --&gt; Done([&quot;取消完成&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-current-node-anim.unit.test.js#L99-L114" target="_blank" rel="noreferrer">test/unit/subtask-current-node-anim.unit.test.js#L99-L114</a></li></ul><h3 id="_5-部分完成语义与失败上报" tabindex="-1">5. 部分完成语义与失败上报 <a class="header-anchor" href="#_5-部分完成语义与失败上报" aria-label="Permalink to &quot;5. 部分完成语义与失败上报&quot;">​</a></h3><p>“部分完成”是一个重要语义修复：当内层 ReAct 循环抛异常但多数节点已成功时，不应简单显示红色“失败”，而应显示橙色“部分完成”，并附带真实中断原因。同时，失败上报给父模型的 Result 中附加已完成节点的产出摘要，避免父模型“带着失败继续”却完全不知道已完成的工作。</p><p>关键实现点：</p><ul><li><code>classifySubtaskOutcome</code> 根据整体状态、成功节点数、总节点数判断是否为部分完成。</li><li>阈值默认 0.8，即成功率 ≥80% 且整体失败时，UI 显示“部分完成”。</li><li>后台通过 <code>recordSubtaskPartialProgress</code> 滚动写入已完成节点摘要，随父 checkpoint 落盘。</li></ul><pre class="mermaid">flowchart TD
Input[&quot;子任务结果&lt;br/&gt;status + succeedNodes + totalNodes&quot;] --&gt; Classify[&quot;classifySubtaskOutcome&quot;]
Classify --&gt; Success{&quot;success ?&quot;}
Success --&gt; |是| MarkDone[&quot;标记为成功&quot;]
Success --&gt; |否| CheckRate{&quot;succeedNodes / totalNodes &gt;= 0.8 ?&quot;}
CheckRate --&gt; |是| Partial[&quot;标记为部分完成&quot;]
CheckRate --&gt; |否| Fail[&quot;标记为失败&quot;]
Partial --&gt; Summary[&quot;buildSubtaskPartialSummary&quot;]
Fail --&gt; Summary
Summary --&gt; ParentReport[&quot;上报父模型 Result&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L760-L760" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L760-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L547-L562" target="_blank" rel="noreferrer">src/background/react-loop.js#L547-L562</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-partial-outcome.unit.test.js#L1-L21" target="_blank" rel="noreferrer">test/unit/subtask-partial-outcome.unit.test.js#L1-L21</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L760-L760" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L760-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L547-L562" target="_blank" rel="noreferrer">src/background/react-loop.js#L547-L562</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-partial-outcome.unit.test.js#L1-L21" target="_blank" rel="noreferrer">test/unit/subtask-partial-outcome.unit.test.js#L1-L21</a></li></ul><h3 id="_6-子任务超时预算与中断原因" tabindex="-1">6. 子任务超时预算与中断原因 <a class="header-anchor" href="#_6-子任务超时预算与中断原因" aria-label="Permalink to &quot;6. 子任务超时预算与中断原因&quot;">​</a></h3><p>早期版本中，子任务曾被硬编码的 15 分钟上限封顶，导致设置页“整体循环超时”对子任务无效。修复后：</p><ul><li>子任务超时上限只由配置值决定。</li><li>父任务可通过 <code>apiParams.subtaskLoopTimeoutMs</code> 注入更紧预算。</li><li>中断文案需包含实际耗时与完整豁免项（澄清等待、敏感操作确认等待）。</li><li>子任务不存自己的 checkpoint，中断即整体失败由父任务重试；因此已完成节点摘要必须回灌，否则重跑等于从零重做。</li></ul><pre class="mermaid">flowchart TD
Config[&quot;设置页 loopTimeout&quot;] --&gt; Compute[&quot;computeSubtaskLoopTimeoutMs&quot;]
ParentBudget[&quot;父任务剩余时间&quot;] --&gt; MinCheck{&quot;是否注入更紧预算？&quot;}
MinCheck --&gt; |是| UseParent[&quot;取 min(loopTimeout, subtaskLoopTimeoutMs)&quot;]
MinCheck --&gt; |否| UseConfig[&quot;使用配置值&quot;]
UseParent --&gt; Timeout[&quot;子任务超时判定&quot;]
UseConfig --&gt; Timeout
Timeout --&gt; Reason[&quot;生成中断原因文案&quot;]
Reason --&gt; Replay[&quot;已完成节点摘要回灌&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1421-L1431" target="_blank" rel="noreferrer">src/background/react-loop.js#L1421-L1431</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-timeout-budget.unit.test.js#L1-L24" target="_blank" rel="noreferrer">test/unit/subtask-timeout-budget.unit.test.js#L1-L24</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1421-L1431" target="_blank" rel="noreferrer">src/background/react-loop.js#L1421-L1431</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-timeout-budget.unit.test.js#L1-L24" target="_blank" rel="noreferrer">test/unit/subtask-timeout-budget.unit.test.js#L1-L24</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>子任务节点动画系统的依赖关系可以概括为：</p><ul><li><strong>chat-manager.js</strong> 依赖后台下发的执行日志，负责解析、渲染、交互。</li><li><strong>chat-streaming.js</strong> 依赖 chat-manager 生成的 DOM，负责取消时的清理。</li><li><strong>styles.css</strong> 被 chat-manager 和 chat-streaming 共同消费，提供视觉与动效。</li><li><strong>react-loop.js</strong> 是数据源，负责子任务计划、执行、进度、超时。</li><li><strong>单元测试</strong> 通过读取源码片段断言行为，属于“源码级回归测试”，而非运行时集成测试。</li></ul><pre class="mermaid">graph LR
RL[&quot;react-loop.js&quot;] --&gt; CM[&quot;chat-manager.js&quot;]
CM --&gt; CS[&quot;chat-streaming.js&quot;]
CM --&gt; STY[&quot;styles.css&quot;]
TEST1[&quot;subtask-current-node-anim.unit.test.js&quot;] --&gt; CM
TEST1 --&gt; STY
TEST2[&quot;subtask-partial-outcome.unit.test.js&quot;] --&gt; CM
TEST3[&quot;subtask-timeout-budget.unit.test.js&quot;] --&gt; RL
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L2902-L2989" target="_blank" rel="noreferrer">src/background/react-loop.js#L2902-L2989</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L902</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4053-L4430" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4053-L4430</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-current-node-anim.unit.test.js#L1-L115" target="_blank" rel="noreferrer">test/unit/subtask-current-node-anim.unit.test.js#L1-L115</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-partial-outcome.unit.test.js#L1-L21" target="_blank" rel="noreferrer">test/unit/subtask-partial-outcome.unit.test.js#L1-L21</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-timeout-budget.unit.test.js#L1-L24" target="_blank" rel="noreferrer">test/unit/subtask-timeout-budget.unit.test.js#L1-L24</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L803-L902" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L803-L902</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4053-L4430" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4053-L4430</a></li></ul><h2 id="性能与可访问性" tabindex="-1">性能与可访问性 <a class="header-anchor" href="#性能与可访问性" aria-label="Permalink to &quot;性能与可访问性&quot;">​</a></h2><h3 id="性能考虑" tabindex="-1">性能考虑 <a class="header-anchor" href="#性能考虑" aria-label="Permalink to &quot;性能考虑&quot;">​</a></h3><ul><li>动效全部基于 CSS，不依赖 JavaScript 动画循环，减少 JS 主线程压力。</li><li>旋转环、呼吸底、图标脉冲仅在 <code>.subtask-progress-active</code> 下生效，避免已完成节点持续消耗 GPU。</li><li>reduced-motion 媒体查询下关闭呼吸底和图标脉冲，仅保留常亮高亮，降低对低性能设备的负担。</li></ul><h3 id="可访问性考虑" tabindex="-1">可访问性考虑 <a class="header-anchor" href="#可访问性考虑" aria-label="Permalink to &quot;可访问性考虑&quot;">​</a></h3><ul><li>使用 <code>prefers-reduced-motion: reduce</code> 提供降级方案，确保对动画敏感的用户仍能感知“当前节点”。</li><li>颜色全部走主题 Token，避免硬编码色值导致暗色模式下对比度不足。</li><li>统计按钮具备 hover 与 active 反馈，提升可点击性。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4158-L4171" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4158-L4171</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4348-L4377" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4348-L4377</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/subtask-current-node-anim.unit.test.js#L85-L96" target="_blank" rel="noreferrer">test/unit/subtask-current-node-anim.unit.test.js#L85-L96</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>排查位置</th><th>修复建议</th></tr></thead><tbody><tr><td>取消后节点仍旋转</td><td>未移除 <code>.subtask-progress-active</code> 或未替换 <code>.subtask-node-spinner</code></td><td><code>chat-streaming.js</code> 的 <code>finalizeCancelledStream</code></td><td>确保移除活动态并将旋转环替换为静态 “○”</td></tr><tr><td>已完成节点一直呼吸</td><td>基础规则自带 animation，未限定在 <code>.subtask-progress-active</code></td><td><code>styles.css</code> 中 <code>.subtask-node-spinner</code> 与 <code>.subtask-node.processing</code></td><td>将 animation 移到 <code>.subtask-progress-active</code> 作用域</td></tr><tr><td>无法区分当前节点</td><td>缺少旋转环/呼吸底/左侧光条</td><td><code>styles.css</code> 当前节点强调块</td><td>检查 keyframes 与作用域是否正确</td></tr><tr><td>部分完成显示为失败</td><td><code>classifySubtaskOutcome</code> 阈值或状态判断错误</td><td><code>chat-manager.js</code></td><td>核对 succeedNodes/totalNodes 与阈值 0.8</td></tr><tr><td>子任务 15 分钟被杀</td><td>仍受硬编码超时限制</td><td><code>react-loop.js</code> 子任务超时计算</td><td>确认放开硬编码上限，改用配置值</td></tr><tr><td>重跑子任务从零开始</td><td>未完成节点摘要未回灌</td><td><code>react-loop.js</code> 的 <code>recordSubtaskPartialProgress</code></td><td>确保随父 checkpoint 落盘</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L2160-L2186" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L2160-L2186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/styles.css#L4111-L4171" target="_blank" rel="noreferrer">src/side_panel/styles.css#L4111-L4171</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L760-L760" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L760-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L547-L562" target="_blank" rel="noreferrer">src/background/react-loop.js#L547-L562</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1421-L1431" target="_blank" rel="noreferrer">src/background/react-loop.js#L1421-L1431</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>子任务节点动画系统通过“后台执行 + 界面渲染 + 样式动效 + 回归测试”四层协作，解决了用户在大量子任务节点中难以识别“当前执行节点”的问题。其设计重点在于：</p><ol><li><strong>作用域隔离</strong>：动效只在 <code>.subtask-progress-active</code> 下生效，避免已完成节点误动。</li><li><strong>取消收敛</strong>：取消链路明确摘掉活动态并还原静态状态位。</li><li><strong>语义清晰</strong>：部分完成与失败分离，失败上报附带已完成节点摘要。</li><li><strong>主题合规</strong>：所有颜色使用 Token，兼容亮/暗/跟随系统主题。</li><li><strong>测试保障</strong>：通过源码级单测锁定关键行为，防止动效回归。</li></ol><p>这套机制不仅提升了用户体验，也为后续扩展更多子任务可视化能力提供了稳定基础。</p>`,104)])])}const b=e(i,[["render",n]]);export{g as __pageData,b as default};
